<?php require_once __DIR__.'/inc/site.php';begin_page('Dictionnaire des paramètres INI','INI settings dictionary','Recherche dans les paramètres et références de lecture du code.','Search settings and code-reading references.');
echo '<div class="searchbar"><input id="query" placeholder="'.e(t('Rechercher un paramètre, une section…','Search a setting, section…')).'" aria-label="Search"><select id="category"><option value="">'.e(t('Toutes les sections','All sections')).'</option></select></div><p id="status"></p><div id="results"></div><button id="loadmore" class="copy" hidden>'.e(t('Afficher plus','Show more')).'</button>';end_page();?>
<script>
(async()=>{let lang="fr";lang=document.documentElement.lang;const esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const parse=s=>{let a=[],row=[],v="",q=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){row.push(v);v=""}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&s[i+1]==='\n')i++;row.push(v);v="";if(row.length>1)a.push(row);row=[]}else v+=c}if(row.length||v){row.push(v);a.push(row)}let cols=a.shift().map(x=>x.replace(/^\ufeff/,''));return a.map(row=>Object.fromEntries(cols.map((k,i)=>[k,row[i]||""])))};let entries=[];try{let r=await fetch("INI.CSV");if(!r.ok)throw Error(r.status);entries=parse(await r.text())}catch(ex){document.querySelector("#status").textContent="INI.CSV unavailable / fichier introuvable";return}let sections=[...new Set(entries.map(e=>e.Section))].sort();const sel=document.querySelector("#category");sel.innerHTML+=sections.map(s=>'<option value="'+esc(s)+'">'+esc(s)+'</option>').join("");let filtered=entries,limit=40;function draw(){let q=document.querySelector("#query").value.toLowerCase(),sec=sel.value;filtered=entries.filter(x=>(!sec||x.Section===sec)&&(!q||[x.Name,x.Section,x.Description,x.Value].some(v=>v.toLowerCase().includes(q))));document.querySelector("#status").textContent=filtered.length+" "+(lang==='fr'?'paramètres':'settings');document.querySelector("#results").innerHTML=filtered.slice(0,limit).map(x=>'<details class="record"><summary>'+esc(x.Name)+' · '+esc(x.Section)+'</summary><p><b>Value:</b> '+esc(x.Value)+' · <b>Type:</b> '+esc(x.Type)+'</p><p>'+esc(x.Description)+'</p><small>'+esc(x.SourceFiles)+'</small><p><small>'+esc(x.IniFiles)+'</small></p></details>').join("");document.querySelector("#loadmore").hidden=filtered.length<=limit}document.querySelector("#query").addEventListener("input",()=>{limit=40;draw()});sel.addEventListener("change",()=>{limit=40;draw()});document.querySelector("#loadmore").addEventListener("click",()=>{limit+=40;draw()});draw();})();
</script>